/**
 * NOVA_ATELIER_WORLD — Bento Metrics Grid
 * 1. COMPOSITION: A 5.5x3.5 bento on a graded stage plane (z=-2.5). One dominant
 *    cell (3.25x3.5) occupies the left column top-to-bottom; two secondary cells
 *    (2.0x1.625 each) stack in the right column with 0.25-unit gutters. A mono
 *    caption header sits 0.5u above the grid, left-aligned to the grid edge.
 * 2. LIGHT RIG: preset rig-tech-clinical — key directional #f2f4f6 @2.2 from
 *    [1.6,3,2.6], fill directional #e6e9ee @1.5 from [-2,2.4,2.2], rim directional
 *    #ffffff @1.0 from [0,2,-3], plus ambient floor 0.34. All node-local.
 * 3. MATERIALS: MeshPhysicalNodeMaterial slabs — surface #14141a, roughness 0.5,
 *    metalness 0.45, clearcoat 0.2 — with a TSL diagonal engineered gradient
 *    (#101017 -> #1a1a22) plus a hard-stop machined sheen band at 40%. A slightly
 *    larger backing slab per cell reads as the 0.04u chamfer catching the rim light.
 * 4. MOTION: entrance = stagger-cards / fade-up (opacity 0->1, y +0.2->0, 500ms,
 *    power2-ish ease) at 80ms stagger, dominant cell first, via gsap. Hover =
 *    press-down (scale->0.97, 120ms) then weighted-settle (1.04->1.0, 900ms).
 * 5. FOCAL ELEMENT: the dominant cell's valueLarge "0.002 mm" — largest type,
 *    brightest sheen band, tick bar accent — is the single brightest read.
 */
import {
  Group,
  Mesh,
  BoxGeometry,
  PlaneGeometry,
  MeshPhysicalNodeMaterial,
  MeshBasicNodeMaterial,
  DirectionalLight,
  AmbientLight,
  Color,
} from 'three/webgpu';
import { uv, mix, vec3, step } from 'three/tsl';
import { gsap } from 'gsap';

const COLORS = {
  background: '#0b0b10',
  surface: '#14141a',
  ink: '#16161d',
  paper: '#e8ecf2',
  accent: '#ff2a38',
  gradA: '#101017',
  gradB: '#1a1a22',
};

function makeGradientColorNode(hexA, hexB) {
  const a = new Color(hexA);
  const b = new Color(hexB);
  const diag = uv().x.add(uv().y).mul(0.5);
  const grad = mix(vec3(a.r, a.g, a.b), vec3(b.r, b.g, b.b), diag);
  const band = step(0.325, diag).mul(step(diag, 0.475));
  return grad.add(band.mul(0.06));
}

function buildBackdrop(ctx, disposables) {
  const { THREE } = ctx;
  const geo = new PlaneGeometry(7, 6);
  const mat = new MeshBasicNodeMaterial();
  mat.colorNode = makeGradientColorNode(COLORS.gradA, COLORS.gradB);
  const mesh = new THREE.Mesh(geo, mat);
  mesh.position.set(0, 0, -2.5);
  disposables.geometries.push(geo);
  disposables.materials.push(mat);
  return mesh;
}

function buildLights(ctx) {
  const group = new Group();
  const ambient = new AmbientLight(0xffffff, 0.34);
  group.add(ambient);

  const key = new DirectionalLight(new Color('#f2f4f6'), 2.2);
  key.position.set(1.6, 3, 2.6);
  key.target.position.set(0, 0.4, 0);
  group.add(key, key.target);

  const fill = new DirectionalLight(new Color('#e6e9ee'), 1.5);
  fill.position.set(-2, 2.4, 2.2);
  fill.target.position.set(0, 0.4, 0);
  group.add(fill, fill.target);

  const rim = new DirectionalLight(new Color('#ffffff'), 1.0);
  rim.position.set(0, 2, -3);
  rim.target.position.set(0, 0.5, 0);
  group.add(rim, rim.target);

  return group;
}

function buildTickBar(ctx, disposables) {
  const { THREE } = ctx;
  const geo = new BoxGeometry(0.4, 0.05, 0.02);
  const mat = new MeshPhysicalNodeMaterial({
    color: new Color(COLORS.accent),
    roughness: 0.4,
    metalness: 0.1,
  });
  mat.emissive = new Color(COLORS.accent);
  mat.emissiveIntensity = 1.3;
  const mesh = new THREE.Mesh(geo, mat);
  disposables.geometries.push(geo);
  disposables.materials.push(mat);
  return mesh;
}

function buildCellSlab(ctx, w, h, disposables) {
  const { THREE } = ctx;
  const group = new Group();

  // chamfer backing slab (slightly larger, sits behind, catches rim light)
  const chamferGeo = new BoxGeometry(w + 0.08, h + 0.08, 0.03);
  const chamferMat = new MeshPhysicalNodeMaterial({
    color: new Color('#22222a'),
    roughness: 0.5,
    metalness: 0.45,
    clearcoat: 0.2,
    clearcoatRoughness: 0.3,
  });
  const chamferMesh = new THREE.Mesh(chamferGeo, chamferMat);
  chamferMesh.position.z = -0.02;
  disposables.geometries.push(chamferGeo);
  disposables.materials.push(chamferMat);
  group.add(chamferMesh);

  // main machined slab surface with engineered gradient
  const slabGeo = new BoxGeometry(w, h, 0.06);
  const slabMat = new MeshPhysicalNodeMaterial({
    roughness: 0.5,
    metalness: 0.45,
    clearcoat: 0.2,
    clearcoatRoughness: 0.3,
  });
  slabMat.colorNode = makeGradientColorNode(COLORS.gradA, COLORS.gradB);
  const slabMesh = new THREE.Mesh(slabGeo, slabMat);
  disposables.geometries.push(slabGeo);
  disposables.materials.push(slabMat);
  group.add(slabMesh);

  return { group, w, h };
}

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const root = new Group();
  root.name = 'bento-metrics-grid';

  const disposables = { geometries: [], materials: [], textures: [] };
  const textNodes = [];

  // ---- bridging idiom for text items ----
  const items =
    config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const findText = (role, text) =>
    items.find((it) => it.role === role && it.text === text) ?? null;

  // ---- STAGE ----
  const backdrop = buildBackdrop(ctx, disposables);
  root.add(backdrop);

  // ---- LIGHT RIG ----
  const lights = buildLights(ctx);
  root.add(lights);

  // ---- GRID GEOMETRY LAYOUT ----
  const gutter = 0.25;
  const gridW = 5.5;
  const gridH = 3.5;
  const domW = 3.25;
  const domH = 3.5;
  const secW = 2.0;
  const secH = 1.625;

  const leftX = -gridW / 2 + domW / 2;
  const rightX = -gridW / 2 + domW + gutter + secW / 2;
  const topRightY = gridH / 2 - secH / 2;
  const bottomRightY = -(gridH / 2 - secH / 2);

  const gridGroup = new Group();
  root.add(gridGroup);

  const cellsForAnim = [];

  // ---- DOMINANT CELL ----
  const domCell = buildCellSlab(ctx, domW, domH, disposables);
  domCell.group.position.set(leftX, 0, 0);
  gridGroup.add(domCell.group);

  const domTick = buildTickBar(ctx, disposables);
  domTick.position.set(-domW / 2 + 0.5 + 0.2, domH / 2 - 0.5 - 0.025, 0.05);
  domCell.group.add(domTick);

  const valueLargeItem = findText('valueLarge', '0.002 mm');
  const valueLargeText = ctx.fontAtlas.createText(
    valueLargeItem?.text ?? '0.002 mm',
    { fontSize: 124, color: COLORS.paper, align: 'left' }
  );
  valueLargeText.position.set(-domW / 2 + 0.5, 0.35, 0.06);
  domCell.group.add(valueLargeText);
  textNodes.push(valueLargeText);

  const labelDomItem = findText('label', 'Case tolerance, CNC pass');
  const labelDomText = ctx.fontAtlas.createText(
    labelDomItem?.text ?? 'Case tolerance, CNC pass',
    { fontSize: 18, color: COLORS.paper, align: 'left' }
  );
  labelDomText.position.set(-domW / 2 + 0.5, 0.35 - 0.5, 0.06);
  domCell.group.add(labelDomText);
  textNodes.push(labelDomText);

  cellsForAnim.push(domCell.group);

  // ---- SECONDARY CELL: TOP RIGHT ----
  const secTop = buildCellSlab(ctx, secW, secH, disposables);
  secTop.group.position.set(rightX, topRightY, 0);
  gridGroup.add(secTop.group);

  const secTopTick = buildTickBar(ctx, disposables);
  secTopTick.position.set(-secW / 2 + 0.5 + 0.2, secH / 2 - 0.5 - 0.025, 0.05);
  secTop.group.add(secTopTick);

  const valueTopItem = findText('value', '38 h');
  const valueTopText = ctx.fontAtlas.createText(valueTopItem?.text ?? '38 h', {
    fontSize: 68,
    color: COLORS.paper,
    align: 'left',
  });
  valueTopText.position.set(-secW / 2 + 0.5, 0.15, 0.06);
  secTop.group.add(valueTopText);
  textNodes.push(valueTopText);

  const labelTopItem = findText('label', 'Power reserve, NA-01');
  const labelTopText = ctx.fontAtlas.createText(
    labelTopItem?.text ?? 'Power reserve, NA-01',
    { fontSize: 18, color: COLORS.paper, align: 'left' }
  );
  labelTopText.position.set(-secW / 2 + 0.5, -0.35, 0.06);
  secTop.group.add(labelTopText);
  textNodes.push(labelTopText);

  cellsForAnim.push(secTop.group);

  // ---- SECONDARY CELL: BOTTOM RIGHT ----
  const secBottom = buildCellSlab(ctx, secW, secH, disposables);
  secBottom.group.position.set(rightX, bottomRightY, 0);
  gridGroup.add(secBottom.group);

  const secBottomTick = buildTickBar(ctx, disposables);
  secBottomTick.position.set(
    -secW / 2 + 0.5 + 0.2,
    secH / 2 - 0.5 - 0.025,
    0.05
  );
  secBottom.group.add(secBottomTick);

  const valueBottomItem = findText('value', '214');
  const valueBottomText = ctx.fontAtlas.createText(
    valueBottomItem?.text ?? '214',
    { fontSize: 68, color: COLORS.paper, align: 'left' }
  );
  valueBottomText.position.set(-secW / 2 + 0.5, 0.15, 0.06);
  secBottom.group.add(valueBottomText);
  textNodes.push(valueBottomText);

  const labelBottomItem = findText('label', 'Components per calibre');
  const labelBottomText = ctx.fontAtlas.createText(
    labelBottomItem?.text ?? 'Components per calibre',
    { fontSize: 18, color: COLORS.paper, align: 'left' }
  );
  labelBottomText.position.set(-secW / 2 + 0.5, -0.35, 0.06);
  secBottom.group.add(labelBottomText);
  textNodes.push(labelBottomText);

  cellsForAnim.push(secBottom.group);

  // ---- HEADER CAPTION ----
  const captionItem = findText('caption', 'ATELIER METRICS / Q2 2026');
  const captionText = ctx.fontAtlas.createText(
    captionItem?.text ?? 'ATELIER METRICS / Q2 2026',
    { fontSize: 18, color: COLORS.paper, align: 'left', letterSpacingPx: 2 }
  );
  captionText.position.set(-2.75, gridH / 2 + 0.5, 0.02);
  root.add(captionText);
  textNodes.push(captionText);

  // ---- MOTION: entrance stagger-cards / fade-up, dominant first ----
  const timelines = [];
  const introTl = gsap.timeline();
  cellsForAnim.forEach((cellGroup, i) => {
    cellGroup.position.y += 0.2;
    cellGroup.scale.setScalar(1);
    const mats = [];
    cellGroup.traverse((o) => {
      if (o.material) mats.push(o.material);
    });
    mats.forEach((m) => {
      m.transparent = true;
      m.opacity = 0;
    });
    introTl.to(
      cellGroup.position,
      { y: cellGroup.position.y - 0.2, duration: 0.5, ease: 'power2.out' },
      i * 0.08
    );
    mats.forEach((m) => {
      introTl.to(m, { opacity: 1, duration: 0.5, ease: 'power2.out' }, i * 0.08);
    });
  });
  timelines.push(introTl);

  // ---- HOVER: press-down + weighted-settle (opt-in via handlers) ----
  const hoverTargets = cellsForAnim;
  let hoverTl = null;
  function onPointerOver() {
    if (hoverTl) hoverTl.kill();
    hoverTl = gsap.timeline();
    hoverTargets.forEach((c) => {
      hoverTl.to(c.scale, { x: 0.97, y: 0.97, z: 0.97, duration: 0.12, ease: 'back.out(2)' }, 0);
    });
    timelines.push(hoverTl);
  }
  function onPointerOut() {
    if (hoverTl) hoverTl.kill();
    hoverTl = gsap.timeline();
    hoverTargets.forEach((c) => {
      hoverTl
        .to(c.scale, { x: 1.04, y: 1.04, z: 1.04, duration: 0.1, ease: 'power2.out' }, 0)
        .to(c.scale, { x: 1, y: 1, z: 1, duration: 0.9, ease: 'power4.out' }, 0.1);
    });
    timelines.push(hoverTl);
  }

  root.userData.handlers = {
    onPointerOver,
    onPointerOut,
  };

  // ---- CLEANUP ----
  root.userData.cleanup = function cleanup() {
    timelines.forEach((tl) => tl.kill());
    if (hoverTl) hoverTl.kill();
    disposables.geometries.forEach((g) => g.dispose());
    disposables.materials.forEach((m) => m.dispose());
    disposables.textures.forEach((t) => t.dispose());
    textNodes.forEach((t) => {
      if (t.geometry) t.geometry.dispose?.();
      if (t.material) t.material.dispose?.();
    });
  };

  return root;
}

