  {"id":"text.label.2","where":"createNode/dominant-cell","how":"ctx.fontAtlas.createText label below valueLarge"},
  {"id":"text.value.3","where":"createNode/secondary-top-cell","how":"ctx.fontAtlas.createText 68px in top-right cell"},
  {"id":"text.label.4","where":"createNode/secondary-top-cell","how":"ctx.fontAtlas.createText label under 38h value"},
  {"id":"text.value.5","where":"createNode/secondary-bottom-cell","how":"ctx.fontAtlas.createText 68px in bottom-right cell"},
